window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5b4f2e060a8edbf3"]={"versions": [{"id": "FIG-5b4f2e060a8edbf3", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> AUTOSAR Feature-Modell / Feature-Diagramm (FODA-Notation – Feature-Oriented Domain Analysis) gemäß Foundation-Spezifikation <code>AUTOSAR_FO_TR_Features</code>.\n</li><li><strong>Technischer Zweck &amp; funktionale Einordnung:</strong> Formale Definition des Foundation-Features <code>FO_TR_FEAT_00127</code> (<strong>SOME/IP</strong> – Scalable service-Oriented MiddlewarE over IP) und dessen plattformübergreifender Variabilitäts-, Abhängigkeits- und Restriktionsbeziehungen zu Transportprotokollen (L4), funktionalen Erweiterungen (E2E) und Sicherheitsarchitekturen (IAM) sowohl für die Classic Platform (CP) als auch die Adaptive Platform (AP).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Zentraler Feature-Knoten:</strong>\n<ul class=\"fig-list\"><li><code>FO_TR_FEAT_00127</code> [<code>SOME_IP</code>]: Primäres Feature für serviceorientierte Kommunikation (RPC-Methoden, Events, Fields, Fire&amp;Forget, Service Discovery).\n</li></ul>\n</li><li><strong>Assoziierte Features &amp; Beziehungssemantik:</strong>\n<ul class=\"fig-list\"><li><code>FO_TR_FEAT_00128</code> [<code>SOME_IP_E2E</code>]: End-to-End-Absicherung von SOME/IP-Nachrichten (CRC, Sequenzzähler, Data ID nach ISO 26262 / ASIL).\n<ul class=\"fig-list\"><li><em>Beziehung:</em> Durchgezogene Linie mit Hohlkreis-Ende (<code>-o</code>) markiert ein <strong>optionales Sub-Feature</strong> (<code>optional decomposition</code>). E2E-Schutz kann bedarfsgerecht pro Event/Methode aktiviert werden.\n</li></ul>\n</li><li><code>FO_TR_FEAT_00173</code> [<code>UDP</code>] &amp; <code>FO_TR_FEAT_00174</code> [<code>TCP</code>]: Transportprotokolle des zugrunde liegenden IP-Kommunikationsstacks.\n<ul class=\"fig-list\"><li><em>Beziehung:</em> Gepunktete gerichtete Kanten mit Stereotyp <code>«restriction»</code>. SOME/IP unterliegt den protokollspezifischen Restriktionen der L4-Transportschicht (z. B. MTU-Grenzen, Paketverlust, Fragmentierungsanforderungen vs. Verbindungsaufbau-Overhead und Byte-Stream-Framing).\n</li></ul>\n</li><li><code>FO_TR_FEAT_00220</code> [<code>Identity_and_Access_Management_IAM</code>]: Berechtigungs- und Zugriffskontrollarchitektur (vorwiegend AP / Security Architecture).\n<ul class=\"fig-list\"><li><em>Beziehung:</em> Gestrichelte gerichtete Kante mit Stereotyp <code>«relation»</code>. Definiert eine funktionale Interaktions- und Kopplungsabhängigkeit: SOME/IP-Dienstaufrufe und -Bereitstellungen interagieren mit IAM zur Autorisierung von Client-Anfragen (Access Control).\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf (falls zutreffend)</h4>\n<p class=\"fig-p\">Als statisches Variabilitäts- und Architekturmodell besitzt das Diagramm keine direkte Laufzeit-Zeitschiene. Aus den Beziehungen resultiert zur Laufzeit folgende Ausführungskette:</p>\n<ol class=\"fig-list\"><li><strong>Verbindungsaufbau &amp; Transportabstraktion:</strong> SOME/IP bindet dynamisch oder statisch an Socket-Endpunkte über <code>TCP</code> oder <code>UDP</code> (<code>«restriction»</code>). Bei UDP greift bei Payloads &gt; Link-MTU das SOME/IP-Transport-Protocol (SOME/IP-TP).\n</li><li><strong>Access Control Evaluation (<code>«relation» IAM</code>):</strong> Vor dem Dispatching von Service-Methoden oder vor dem Abonnement von Events validiert das System über IAM/PDP (Policy Decision Point) die Berechtigung des aufrufenden Prozesses / Clients.\n</li><li><strong>E2E-Transformation (<code>optional SOME_IP_E2E</code>):</strong> Vor der Serialisierung (Sender) wird der E2E-Header kalkuliert; nach der Deserialisierung (Receiver) erfolgt die Auswertung von Replay-Attacks, Out-of-Order-Zuständen und Payload-Integrität.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Classic Platform (CP):</strong>\n<ul class=\"fig-list\"><li>Bindeglied im BSW-Stack: <code>SomeIpXf</code> (SOME/IP Transformer) → <code>SoAd</code> (Socket Adaptor) → <code>TcpIp</code>.\n</li><li>Die Wahl zwischen <code>TCP</code> und <code>UDP</code> diktiert die <code>SoAdSocketConnectionGroup</code>- und PDU-Routing-Tabellen sowie PBuffer-Verwaltung.\n</li><li>Aktivierung von <code>FO_TR_FEAT_00128</code> erfordert die Konfiguration der <code>E2EXf</code> (E2E Transformer) im Signal-/Transformer-Chain-Pfad des RTE.\n</li></ul>\n</li><li><strong>Adaptive Platform (AP):</strong>\n<ul class=\"fig-list\"><li>Implementierung über <code>ara::com</code> und das entsprechende Plattform-Binding (SOME/IP-Daemon / Binding).\n</li><li>IAM-Restriktionen bedingen Zugriffsrichtlinien in den Manifesten (<code>ServiceInstanceDeployment</code>, <code>Grant</code>, <code>ProcessExecutionManifest</code>) zur Interaktion mit <code>ara::iam</code>.\n</li></ul>\n</li><li><strong>Spezifikationsverträge:</strong>\n<ul class=\"fig-list\"><li>Verbindlich geregelt in <code>AUTOSAR_PRS_SOMEIPProtocol</code>, <code>AUTOSAR_PRS_SOMEIPServiceDiscoveryProtocol</code> und <code>AUTOSAR_PRS_E2EProtocol</code>.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-9763618ec984809b", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> AUTOSAR Feature-Modell / Feature-Diagramm (FODA-Notation – Feature-Oriented Domain Analysis) gemäß Foundation-Spezifikation <code>AUTOSAR_FO_TR_Features</code>.\n</li><li><strong>Technischer Zweck &amp; funktionale Einordnung:</strong> Formale Definition des Foundation-Features <code>FO_TR_FEAT_00127</code> (<strong>SOME/IP</strong> – Scalable service-Oriented MiddlewarE over IP) und dessen plattformübergreifender Variabilitäts-, Abhängigkeits- und Restriktionsbeziehungen zu Transportprotokollen (L4), funktionalen Erweiterungen (E2E) und Sicherheitsarchitekturen (IAM) sowohl für die Classic Platform (CP) als auch die Adaptive Platform (AP).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Zentraler Feature-Knoten:</strong>\n<ul class=\"fig-list\"><li><code>FO_TR_FEAT_00127</code> [<code>SOME_IP</code>]: Primäres Feature für serviceorientierte Kommunikation (RPC-Methoden, Events, Fields, Fire&amp;Forget, Service Discovery).\n</li></ul>\n</li><li><strong>Assoziierte Features &amp; Beziehungssemantik:</strong>\n<ul class=\"fig-list\"><li><code>FO_TR_FEAT_00128</code> [<code>SOME_IP_E2E</code>]: End-to-End-Absicherung von SOME/IP-Nachrichten (CRC, Sequenzzähler, Data ID nach ISO 26262 / ASIL).\n<ul class=\"fig-list\"><li><em>Beziehung:</em> Durchgezogene Linie mit Hohlkreis-Ende (<code>-o</code>) markiert ein <strong>optionales Sub-Feature</strong> (<code>optional decomposition</code>).\n</li></ul>\n</li><li><code>FO_TR_FEAT_00264</code> [<code>SOME_IP_TP</code>]: Transport-Protocol-Erweiterung für SOME/IP zur Segmentierung und Reassemblierung von Nachrichten, die die MTU überschreiten (insbesondere über UDP).\n<ul class=\"fig-list\"><li><em>Beziehung:</em> Durchgezogene Linie mit Hohlkreis-Ende (<code>-o</code>) markiert ein <strong>optionales Sub-Feature</strong> (<code>optional decomposition</code>).\n</li></ul>\n</li><li><code>FO_TR_FEAT_00173</code> [<code>UDP</code>] &amp; <code>FO_TR_FEAT_00174</code> [<code>TCP</code>]: Transportprotokolle des zugrunde liegenden IP-Kommunikationsstacks.\n<ul class=\"fig-list\"><li><em>Beziehung:</em> Gepunktete gerichtete Kanten mit Stereotyp <code>«restriction»</code>. SOME/IP unterliegt den protokollspezifischen Restriktionen der L4-Transportschicht.\n</li></ul>\n</li><li><code>FO_TR_FEAT_00220</code> [<code>Identity_and_Access_Management_IAM</code>]: Berechtigungs- und Zugriffskontrollarchitektur (vorwiegend AP / Security Architecture).\n<ul class=\"fig-list\"><li><em>Beziehung:</em> Gestrichelte gerichtete Kante mit Stereotyp <code>«relation»</code>. Definiert eine funktionale Interaktions- und Kopplungsabhängigkeit zur Autorisierung von Client-Anfragen (Access Control).\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Variabilitäts- und Architekturmodell besitzt das Diagramm keine direkte Laufzeit-Zeitschiene. Aus den Beziehungen resultiert zur Laufzeit folgende Ausführungskette:</p>\n<ol class=\"fig-list\"><li><strong>Verbindungsaufbau &amp; Transportabstraktion:</strong> SOME/IP bindet dynamisch oder statisch an Socket-Endpunkte über <code>TCP</code> oder <code>UDP</code> (<code>«restriction»</code>). Bei UDP greift bei Payloads &gt; Link-MTU das SOME/IP-Transport-Protocol (SOME/IP-TP).\n</li><li><strong>Access Control Evaluation (<code>«relation» IAM</code>):</strong> Vor dem Dispatching von Service-Methoden oder vor dem Abonnement von Events validiert das System über IAM/PDP (Policy Decision Point) die Berechtigung des aufrufenden Prozesses / Clients.\n</li><li><strong>E2E-Transformation (<code>optional SOME_IP_E2E</code>):</strong> Vor der Serialisierung (Sender) wird der E2E-Header kalkuliert; nach der Deserialisierung (Receiver) erfolgt die Auswertung von Replay-Attacks, Out-of-Order-Zuständen und Payload-Integrität.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Classic Platform (CP):</strong>\n<ul class=\"fig-list\"><li>Bindeglied im BSW-Stack: <code>SomeIpXf</code> (SOME/IP Transformer) → <code>SoAd</code> (Socket Adaptor) → <code>TcpIp</code>.\n</li><li>Die Wahl zwischen <code>TCP</code> und <code>UDP</code> diktiert die <code>SoAdSocketConnectionGroup</code>- und PDU-Routing-Tabellen sowie PBuffer-Verwaltung.\n</li><li>Aktivierung von <code>FO_TR_FEAT_00128</code> erfordert die Konfiguration der <code>E2EXf</code> (E2E Transformer) im Signal-/Transformer-Chain-Pfad des RTE.\n</li></ul>\n</li><li><strong>Adaptive Platform (AP):</strong>\n<ul class=\"fig-list\"><li>Implementierung über <code>ara::com</code> und das entsprechende Plattform-Binding (SOME/IP-Daemon / Binding).\n</li><li>IAM-Restriktionen bedingen Zugriffsrichtlinien in den Manifesten (<code>ServiceInstanceDeployment</code>, <code>Grant</code>, <code>ProcessExecutionManifest</code>) zur Interaktion mit <code>ara::iam</code>.\n</li></ul>\n</li><li><strong>Spezifikationsverträge:</strong>\n<ul class=\"fig-list\"><li>Verbindlich geregelt in <code>AUTOSAR_PRS_SOMEIPProtocol</code>, <code>AUTOSAR_PRS_SOMEIPServiceDiscoveryProtocol</code> und <code>AUTOSAR_PRS_E2EProtocol</code>.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-5b4f2e060a8edbf3", "to": "FIG-9763618ec984809b", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Hinzufügung des optionalen Sub-Features <code>FO_TR_FEAT_00264</code> (<code>SOME_IP_TP</code>) unterhalb von <code>FO_TR_FEAT_00127</code> (<code>SOME_IP</code>) mit FODA-Dekompositionskante (durchgezogene Linie mit Hohlkreis).\n</li></ul>"}]};
